"shatter": { does: "A sudden loud ringing noise, painfully intense, erupts from a point of your choice. A creature made of inorganic material has disadvantage on the save.", dur: "instantaneous", range: "60 feet", area: "10-foot radius" },
"silence": { does: "For the duration, no sound can be created within or pass through a 20-foot-radius sphere. Creatures inside are immune to thunder damage and are deafened.", dur: "concentration, up to 10 minutes", range: "120 feet", area: "20-foot radius", conc: true },
"spider climb": { does: "Until the spell ends, one willing creature you touch gains the ability to move up, down, and across vertical surfaces and upside down along ceilings, while leaving its hands free.", dur: "concentration, up to 1 hour", range: "touch", conc: true },
"spike growth": { does: "The ground in a 20-foot radius twists into hard spikes. The area is difficult terrain, and a creature takes piercing damage for every 5 feet it moves through it.", dur: "concentration, up to 10 minutes", range: "150 feet", area: "20-foot radius", conc: true },
"spiritual weapon": { does: "You create a floating weapon of force. When you cast the spell you can make a melee spell attack, and as a bonus action on later turns you can move it and attack again.", dur: "1 minute", range: "60 feet" },
"suggestion": { does: "You suggest a course of activity, limited to a sentence or two, to one creature that can hear and understand you. On a failed Wisdom save it pursues the course of action.", dur: "concentration, up to 8 hours", range: "30 feet", conc: true },
"warding bond": { does: "You touch a willing creature and create a mystic connection. While you are within 60 feet, it has a +1 bonus to AC and saving throws and resistance to all damage, and you take the same damage it does.", dur: "1 hour", range: "touch" },
"web": { does: "You conjure a mass of thick webbing in a 20-foot cube. The webs are difficult terrain and lightly obscure the area. A creature that starts its turn there or enters it must succeed on a Dexterity save or be restrained.", dur: "concentration, up to 1 hour", range: "60 feet", area: "20-foot cube", conc: true },
"zone of truth": { does: "You create a magical zone that guards against deception in a 15-foot-radius sphere. A creature that fails a Charisma save cannot speak a deliberate lie while in the radius.", dur: "10 minutes", range: "60 feet", area: "15-foot radius" },
"beacon of hope": { does: "This spell bestows hope and vitality. Each target has advantage on Wisdom saves and death saves, and regains the maximum number of hit points from healing.", dur: "concentration, up to 1 minute", range: "30 feet", conc: true },
"bestow curse": { does: "You touch a creature, and it must succeed on a Wisdom save or become cursed for the duration. You choose one penalty, such as disadvantage on checks and saves with one ability.", dur: "concentration, up to 1 minute", range: "touch", conc: true },
"blinding smite": { does: "The next time you hit a creature with a melee weapon attack, the attack deals extra radiant damage and the target must succeed on a Constitution save or be blinded.", dur: "concentration, up to 1 minute", range: "self", conc: true },
"blink": { does: "Roll a d20 at the end of each of your turns. On an 11 or higher you vanish into the Ethereal Plane and return at the start of your next turn.", dur: "1 minute", range: "self" },
"call lightning": { does: "A storm cloud appears and you can call down lightning as an action. A creature in a 5-foot radius must make a Dexterity save. You can call another bolt on later turns.", dur: "concentration, up to 10 minutes", range: "120 feet", area: "5-foot radius", conc: true },
"clairvoyance": { does: "You create an invisible sensor in a location familiar to you or an obvious location you have not seen. You can see or hear through the sensor.", dur: "concentration, up to 10 minutes", range: "1 mile", conc: true },
