"dispel magic": { does: "Choose one creature, object, or magical effect within range. Any spell of 3rd level or lower on the target ends. For each spell of 4th level or higher, make an ability check using your spellcasting ability.", dur: "instantaneous", range: "120 feet" },
"fear": { does: "You project a phantasmal image of a creature's worst fears in a 30-foot cone. Each creature must succeed on a Wisdom save or drop what it is holding and become frightened.", dur: "concentration, up to 1 minute", range: "self", area: "30-foot cone", conc: true },
"feign death": { does: "You touch a willing creature and put it into a cataleptic state that is indistinguishable from death.", dur: "1 hour", range: "touch" },
"fireball": { does: "A bright streak flashes from your pointing finger to a point you choose and blossoms into an explosion of flame. A successful save halves the damage.", dur: "instantaneous", range: "150 feet", area: "20-foot radius" },
"fly": { does: "You touch a willing creature. The target gains a flying speed of 60 feet for the duration.", dur: "concentration, up to 10 minutes", range: "touch", conc: true },
