"slow": { does: "You alter time around up to six creatures of your choice in a 40-foot cube. Each target must succeed on a Wisdom save or be slowed: its speed is halved, it takes a penalty to AC and Dexterity saves, and it cannot use reactions.", dur: "concentration, up to 1 minute", range: "120 feet", area: "40-foot cube", conc: true },
