"vampiric touch": { does: "The touch of your shadow-wreathed hand can siphon life. Make a melee spell attack. On a hit you regain hit points equal to half the necrotic damage dealt.", dur: "concentration, up to 1 minute", range: "self", conc: true },
"water breathing": { does: "This spell grants up to ten willing creatures you can see the ability to breathe underwater until the spell ends.", dur: "24 hours", range: "30 feet" },
"water walk": { does: "This spell grants the ability to move across any liquid surface as if it were harmless solid ground. Up to ten willing creatures you can see gain this ability.", dur: "1 hour", range: "30 feet" },
"wind wall": { does: "A wall of strong wind rises from the ground. The wall is 50 feet long, 15 feet high, and 1 foot thick. Ranged weapon attacks that pass through it have disadvantage.", dur: "concentration, up to 1 minute", range: "120 feet", area: "50-foot wall", conc: true }
